package main

import (
	"bufio"
	"encoding/json"
	"fmt"
	"os"
	"strings"
	"sync"
)

var (
	id       int
	neighbors map[string][]string
	mu       sync.Mutex
)

type TellRequest struct {
	Type     string `json:"type"`
	MsgID    int    `json:"msg_id,omitempty"`
	Rumor    int    `json:"rumor,omitempty"`
	InReplyTo int   `json:"in_reply_to,omitempty"`
}

func handleTell(req *TellRequest) (int, error) {
	mu.Lock()
	defer mu.Unlock()

	if req.Type == "tell" && req.Rumor > 0 {
		// Store this rumor in our own set
		nodeRumors[req.MsgID] = append(nodeRumors[req.MsgID], int(req.Rumor))
	}

	// Send to neighbors - but we only do this once per neighbor per rumor event
	for _, nb := range neighbors {
		for i, nm := range neighbors[nb] {
			mu.Lock()
			if !neighborsToSend[int(id)][nm] {
				// Create send message for gossip
				sendMsg := &TellMessage{
					Type: "tell",
					MsgID: req.MsgID + 1,
					Rumor: int(req.Rumor),
				}
				writeJSON(&sendMsg)
			}
			mu.Unlock()
		}
	}

	return 0, nil
}

func writeJSON(msg *TellMessage) {
	jsonBytes, _ := json.Marshal(msg)
	fmt.Fprintf(os.Stdout, "%s\n", jsonBytes)
}

func main() {
	reader := bufio.NewReader(os.Stdin)

	for line, err := reader.ReadString('\n'); len(line) > 0 || err == nil; line = nextLine(reader) {
		if err != nil {
			break
		}

		var req TellRequest
		if err := json.Unmarshal([]byte(strings.TrimSpace(line)), &req); err != nil {
			continue
		}

		switch req.Type {
		case "init":
			id = int(req.ID)
			neighbors = req.Neighbors
			nodeRumors[int(id)] = []int{}
			for i := 0; i <= id+3; i++ {
				neighborsToSend[int(id)][fmt.Sprintf("%d", i)] = false
			}

		case "tell":
			rumor, _ := req.GetRumor()
			if err := handleTell(&req); err != nil {
				fmt.Fprintln(os.Stderr, err.Error())
			}

		case "recall":
			mu.Lock()
			rumors := []int(nil)
			if len(nodeRumors[req.MsgID]) > 0 {
				rumors = sortedInts(nodeRumors[req.MsgID])
			}
			response := &TellResponse{
				Type:     "recalled",
				InReplyTo: req.MsgID,
				Rumors:   rumors,
			}
			jsonBytes, _ := json.Marshal(response)
			fmt.Fprintf(os.Stdout, "%s\n", jsonBytes)
			mu.Unlock()

		case "neighbors":
			// Process neighbors topology (may come before tell/recall)
			// For now, just note it
			// HandleNeighbors(&req)

		default:
		}

		if req.Type == "tell" {
			_ = handleTell(&req)
		}
	}
}

func nextLine(r *bufio.Reader) string {
	line, err := r.ReadString('\n')
	if err != nil {
		return ""
	}
	return line
}

