	InReplyTo int   `json:"in_reply_to,omitempty"`
	Rumors   []int  `json:"rumors,omitempty"`
	Neighbors map[string][]string `json:"neighbors,omitempty"`
}

type TellMessage struct {
	Type     string `json:"type"`
	MsgID    int    `json:"msg_id,omitempty"`
	Rumor    int    `json:"rumor,omitempty"`
}

type TellResponse struct {
	Type     string `json:"type"`
	InReplyTo int   `json:"in_reply_to,omitempty"`
	Rumors   []int  `json:"rumors,omitempty"`
}

var (
	id       int
	nodeRumors = make(map[int][]int) // local node ID -> list of rumors
	neighbors map[string][]string
	mu        sync.Mutex
)

func nextLine(r *bufio.Reader) string {
	line, err := r.ReadString('\n')
	if err != nil {
		return ""
	}
	return line
}

func handleTell(req *MaelstromRequest) error {
	switch req.Type {
	case "tell":
		rumorID := int(req.Rumor)
		msgID := int(req.MsgID)
		mu.Lock()
		nodeRumors[req.ID] = append(nodeRumors[req.ID], rumorID)
		mu.Unlock()

		// Send to all neighbors that we can reach
		if req.ID < len(neighbors) {
			for neighbor, targets := range neighbors[req.ID] {
				if targetIdx := int(req.ID + 1); targetIdx < len(targets) {
					mu.Lock()
					// Check if we've already sent to this node (to avoid duplicates in test)
					if !neighborsToSend[targetIdx][neighbor] {
						sendMsg := &TellMessage{
							Type: "tell",
							MsgID: msgID,
							Rumor: rumorID,
						}
						fmt.Fprintf(os.Stdout, "%s\n", jsonBytesFrom(sendMsg))
						neighborsToSend[targetIdx][neighbor] = true
					}
					mu.Unlock()
				}
			}
		}
	case "told":
		msgID := int(req.InReplyTo)
		return nil
	default:
		return fmt.Errorf("unknown message type: %s", req.Type)
	}
	return nil
}

func sendRumors() {
	mu.Lock()
	defer mu.Unlock()

	// Collect all rumors from this node
	localRumors := []int(nil)
	if len(nodeRumors[int(id)]) > 0 {
		localRumors = copyInts(nodeRumors[int(id)])
	}

	for _, rumor := range localRumors {
		sendMsg := &TellMessage{
			Type: "tell",
			Rumor: rumor,
		}
		fmt.Fprintf(os.Stdout, "%s\n", jsonBytesFrom(sendMsg))
	}
}

func copyInts(src []int) []int {
	dst := make([]int, len(src))
	copy(dst, src)
	return dst
}

func jsonBytesFrom(v interface{}) []byte {
	jsonBytes, _ := json.Marshal(v)
	return jsonBytes
}

func main() {
	reader := bufio.NewReader(os.Stdin)

	var mReq MaelstromRequest

	for line, err := reader.ReadString('\n'); len(line) > 0 || err != nil; line = nextLine(reader) {
		if err != nil {
			break
		}

		if err := json.Unmarshal([]byte(strings.TrimSpace(line)), &mReq); err != nil {
			continue
		}

		switch mReq.Type {
		case "init":
			id = int(mReq.ID)
			nodeRumors[int(id)] = []int{}
			// Initialize node IDs in range (we'll be one of them)
			neighbors = mReq.Neighbors
			for i := 0; i < len(neighbors); i++ {
				neighborsToSend[i+1] = map[string]bool{}
				if neighbor, ok := neighbors[int(i)]; ok && neighbor != "" {
					for _, target := range neighbor {
						neighborsToSend[i+1][target] = true
					}
				}
			}

		case "tell":
			rumor := int(mReq.Rumor)
			msgID := int(mReq.MsgID)
			handleTell(&MaelstromRequest{
				Type:     mReq.Type,
				ID:       id,
				MsgID:    msgID,
				Rumor:    rumor,
			})

		case "recall":
			msgID := int(mReq.MsgID)
			resp := &TellResponse{
				Type:     "recalled",
				InReplyTo: mReq.InReplyTo,
				Rumors:   make([]int, 0),
			}

			mu.Lock()
			rumors := []int(nil)
			if len(nodeRumors[int(id)]) > 0 {
				rumors = copyInts(nodeRumors[int(id)])
			}
			resp.Rumors = rumors
			mu.Unlock()

			jsonBytes, _ := json.Marshal(resp)
			fmt.Fprintf(os.Stdout, "%s\n", jsonBytes)

		case "neighbors":
			// Store neighbors topology - already done in init handling above

		case "neighbors_noted":
			return nil
		}

		if mReq.Type == "tell" {
			rumor := int(mReq.Rumor)
			msgID := int(mReq.MsgID)
			handleTell(&MaelstromRequest{
				Type:     mReq.Type,
				ID:       id,
				MsgID:    msgID,
				Rumor:    rumor,
			})
		}
	}
}

package main

import (
	"bufio"
	"encoding/json"
	"fmt"
	"os"
	"strings"
	"sync"
)

// This node handles gossip protocol for a village of gossips.
// Each rumor is passed from one node to its neighbors until known by all.
// Nodes communicate via stdin/stdout JSON messages.

var (
	id           int
	neighbors    = make(map[int][]int) // local ID -> list of neighbor IDs
	nodeRumors   = make(map[int]map[int]bool) // local ID -> rumorID -> bool set
	sendedTo     = make(map[int]map[int]bool) // local ID -> neighbor ID -> send flag

	mu sync.Mutex
)

func nextLine(r *bufio.Reader) string {
	line, err := r.ReadString('\n')
	if err != nil {
		return ""
	}
	return line
}

func handleTell(req interface{}) error {
	tellReq := req.(*TellRequest)
	msgID := tellReq.MsgID
	rumor := tellReq.Rumor

	mu.Lock()
	nodeRumors[tellReq.ID][rumor] = true
	// Mark this rumor as already being processed locally
	sendedTo[tellReq.ID][rumor] = true
	mu.Unlock()

	// Send to all neighbors we know about
	if tellReq.ID != 0 { // Check if initialized
		for _, neighborID := range neighbors[tellReq.ID] {
			mu.Lock()
			// Only send if not already sent on this iteration for this rumor
			if !sendedTo[neighborID][rumor] {
				sendMsg := &TellMessage{
					Type: "tell",
					MsgID: msgID,
					Rumor: rumor,
				}
				fmt.Fprintf(os.Stdout, "%s\n", jsonBytesFrom(sendMsg))
				sendedTo[neighborID][rumor] = true
			}
			mu.Unlock()
		}
	}

	return nil
}

func sendRumors(nodeID int) {
	if nodeID == 0 {
		return
	}
	mu.Lock()
	defer mu.Unlock()

	for rumor, sent := range sendedTo[nodeID] {
		sendMsg := &TellMessage{
			Type: "tell",
			Rumor: rumor,
		}
		if sent[true] {
			continue // Already sent
		}
		fmt.Fprintf(os.Stdout, "%s\n", jsonBytesFrom(sendMsg))
	}
}

func sendToNeighbor(nodeID, neighborID int) {
	mu.Lock()
	rumors := nodeRumors[nodeID]
	for rumor := range rumors {
		sendedTo[neighborID][rumor] = true
	}
	mu.Unlock()

	if len(neighbors[nodeID]) == 0 || neighbors[nodeID] == nil {
		return
	}

	for _, neighbor := range neighbors[nodeID] {
		if neighbor == 0 {
			continue
		}
		sendToNeighbor(nodeID, neighbor)
	}
}

func jsonBytesFrom(v interface{}) []byte {
	jsonBytes, _ := json.Marshal(v)
	return jsonBytes
}

type TellRequest struct {
	Type     string `json:"type"`
	ID       int    `json:"id,omitempty"`
	MsgID    int    `json:"msg_id,omitempty"`
	Rumor    int    `json:"rumor,omitempty"`
	InReplyTo int   `json:"in_reply_to,omitempty"`
	Neighbors map[string][]string `json:"neighbors,omitempty"`
}

type TellMessage struct {
	Type string `json:"type"`
	MsgID int  `json:"msg_id,omitempty"`
	Rumor int  `json:"rumor,omitempty"`
}

func main() {
	reader := bufio.NewReader(os.Stdin)

	for line, err := reader.ReadString('\n'); len(line) > 0 || err != nil; line = nextLine(reader) {
		if err != nil {
			break
		}

		var req TellRequest
		json.Unmarshal([]byte(strings.TrimSpace(line)), &req)

		switch req.Type {
		case "init":
			id = int(req.ID)
			nodeRumors[id] = make(map[int]bool)
			for nid, nbrs := range neighbors {
				sendedTo[nid] = make(map[int]bool)
				for _, nbr := range nbrs {
					if nbr != "" {
						sendedTo[nid][nbr] = true
					}
				}
			}
			// Initialize send flags for this node's rumors
			nodeRumors[id][0] = true
			sendedTo[id][0] = true

		case "tell":
			handleTell(&req)

		case "recall":
			resp := &TellResponse{
				Type:     "recalled",
				InReplyTo: int(req.InReplyTo),
				Rumors:   []int(nil),
			}

			mu.Lock()
			rumors := make([]int, 0)
			if len(nodeRumors[int(id)]) > 0 {
				for r := range nodeRumors[int(id)] {
					rumors = append(rumors, int(r))
				}
			}
			resp.Rumors = sortedInts(rumors)
			mu.Unlock()

			jsonBytes, _ := json.Marshal(resp)
			fmt.Fprintf(os.Stdout, "%s\n", jsonBytes)

		case "neighbors":
			// Already handled in init - note: neighbors are provided here too
			// Store them for later use

		default:
		}

		if req.Type == "tell" {
			handleTell(&req)
		}
	}
}

func sortedInts(src []int) []int {
	dst := make([]int, len(src))
	copy(dst, src)
	for i := 0; i < len(dst); i++ {
		for j := i + 1; j < len(dst); j++ {
			if dst[j] < dst[i] {
				dst[i], dst[j] = dst[j], dst[i]
			}
		}
	}
	return dst
}

