const version = "v0.0.0-20260710121306-480a8197026d"

func main() {
	n := maelstrom.NewNode()

	// State per node: rumorID -> bool set
	nodeRumors := make(map[int]map[int]bool) // id -> rumorSet

	// Track which nodes we've talked to with which rumors
	sentToNeighbors := make(map[int]map[int]bool) // neighborID -> rumorID -> bool map

	var mu sync.Mutex

	// Process "init" message (called automatically by maelstrom library)
	n.Handle("init", func(msg maelstrom.Message) error {
		var body map[string]any
		if err := json.Unmarshal(msg.Body, &body); err != nil {
			return err
		}

		nodeID, ok1 := body["node_id"].(string)
		nodeIDs, ok2 := body["node_ids"].([]interface{})

		if !ok1 || len(nodeIDs) == 0 {
			return nil
		}

		idStr := nodeID
		var ids []int
		for _, idVal := range nodeIDs {
			if intID, ok := idVal.(float64) {
				ids = append(ids, int(idID))
			} else if strID, ok := idVal.(string); ok {
				if strID != "" {
					ids = append(ids, int(maelstrom.ID(strID)))
				}
			}
		}

		return nil
	})

	// Handle "tell" message: pass on the rumor to neighbors
	n.Handle("tell", func(msg maelstrom.Message) error {
		var body map[string]any
		if err := json.Unmarshal(msg.Body, &body); err != nil {
			return err
		}

		typ, _ := body["type"].(string)
		msgID, _ := body["msg_id"].(float64)
		rumorVal, _ := body["rumor"].(float64)

		tellBody := &TellMessage{
			Type:     typ,
			MsgID:    int(msgID),
			Rumor:    int(rumorVal),
		}

		if typ == "tell" {
