			servedTo := make(map[int]bool)
			for r := range rumorsSet {
				servedTo[r] = true
			}
			nodeRumors[int(id)] = servedTo

			if len(nodeRumors[int(id)]) > 0 {
				mu.Lock()
				rumorsToSend := nodeRumors[int(id)]
				mu.Unlock()

				for _, neighbor := range neighbors[int(id)] {
					mu.Lock()
					// Send to neighbors that we haven't already sent to for this rumor
